from collections import deque

def bfs_shortest(graph, start, goal):
    q = deque([(start, [start])])
    seen = {start}
    while q:
        node, path = q.popleft()
        if node == goal:
            return path              # first arrival = fewest hops
        for nb in graph[node]:
            if nb not in seen:
                seen.add(nb)
                q.append((nb, path + [nb]))
    return None

